//! Analysis of why F64 ramp is 2x faster than F32 ramp even after optimization
//!
//! This investigates the XOR patterns generated by linear ramp data

use timbre_tsf::common::{TSDataType, TSEncoding};
use timbre_tsf::encoding::create_encoder;
use std::time::Instant;

fn analyze_xor_pattern() {
    println!("\n=== XOR Pattern Analysis for Ramp ===\n");

    // Analyze F32 ramp XOR pattern
    println!("F32 Ramp (i as f32 * 0.1):");
    let mut prev: Option<u32> = None;
    let mut total_sig_bits = 0u64;
    let mut count = 0;

    for i in 0..20 {
        let val = (i as f32 * 0.1).to_bits();
        if let Some(p) = prev {
            let xor = val ^ p;
            let leading = xor.leading_zeros();
            let trailing = xor.trailing_zeros();
            let significant = 32 - leading - trailing;
            println!("  i={:2}: val={:08x}, xor={:08x}, lead={:2}, trail={:2}, sig={:2}",
                     i, val, xor, leading, trailing, significant);
            total_sig_bits += significant as u64;
            count += 1;
        } else {
            println!("  i={:2}: val={:08x} (first)", i, val);
        }
        prev = Some(val);
    }
    println!("  Average significant bits: {:.2}", total_sig_bits as f64 / count as f64);

    // Analyze F64 ramp XOR pattern
    println!("\nF64 Ramp (i as f64 * 0.1):");
    let mut prev_f64: Option<u64> = None;
    let mut total_sig_bits_f64 = 0u64;
    let mut count_f64 = 0;

    for i in 0..20 {
        let val = (i as f64 * 0.1).to_bits();
        if let Some(p) = prev_f64 {
            let xor = val ^ p;
            let leading = xor.leading_zeros();
            let trailing = xor.trailing_zeros();
            let significant = 64 - leading - trailing;
            println!("  i={:2}: val={:016x}, xor={:016x}, lead={:2}, trail={:2}, sig={:2}",
                     i, val, xor, leading, trailing, significant);
            total_sig_bits_f64 += significant as u64;
            count_f64 += 1;
        } else {
            println!("  i={:2}: val={:016x} (first)", i, val);
        }
        prev_f64 = Some(val);
    }
    println!("  Average significant bits: {:.2}", total_sig_bits_f64 as f64 / count_f64 as f64);
}

fn measure_ramp_encoding() {
    println!("\n=== Ramp Encoding Performance ===\n");

    const NUM_VALUES: usize = 1_000_000;
    const ITERATIONS: usize = 50;

    let ramp_f32: Vec<f32> = (0..NUM_VALUES).map(|i| i as f32 * 0.1).collect();
    let ramp_f64: Vec<f64> = (0..NUM_VALUES).map(|i| i as f64 * 0.1).collect();

    // F32 Gorilla
    let start = Instant::now();
    let mut total_bytes = 0;
    for _ in 0..ITERATIONS {
        let mut encoder = create_encoder(TSEncoding::Gorilla, TSDataType::Float);
        let mut out = Vec::new();
        for &v in &ramp_f32 {
            encoder.encode_f32(v, &mut out).unwrap();
        }
        encoder.flush(&mut out).unwrap();
        total_bytes = out.len();
    }
    let duration_f32 = start.elapsed();
    let throughput_f32 = (total_bytes * ITERATIONS) as f64 / duration_f32.as_secs_f64() / (1024.0 * 1024.0);
    println!("Gorilla F32 ramp:");
    println!("  Throughput: {:.2} MiB/s", throughput_f32);
    println!("  Compressed size: {} bytes ({:.2} bits/value)", total_bytes, (total_bytes * 8) as f64 / NUM_VALUES as f64);

    // F64 Gorilla
    let start = Instant::now();
    let mut total_bytes = 0;
    for _ in 0..ITERATIONS {
        let mut encoder = create_encoder(TSEncoding::Gorilla, TSDataType::Double);
        let mut out = Vec::new();
        for &v in &ramp_f64 {
            encoder.encode_f64(v, &mut out).unwrap();
        }
        encoder.flush(&mut out).unwrap();
        total_bytes = out.len();
    }
    let duration_f64 = start.elapsed();
    let throughput_f64 = (total_bytes * ITERATIONS) as f64 / duration_f64.as_secs_f64() / (1024.0 * 1024.0);
    println!("\nGorilla F64 ramp:");
    println!("  Throughput: {:.2} MiB/s", throughput_f64);
    println!("  Compressed size: {} bytes ({:.2} bits/value)", total_bytes, (total_bytes * 8) as f64 / NUM_VALUES as f64);

    println!("\nRatio: F64 is {:.2}x faster", throughput_f64 / throughput_f32);
    println!("\nHypothesis:");
    println!("  If F32 generates ~31 bits/value and F64 generates ~63 bits/value,");
    println!("  then F64 should hit the 64-bit batch path frequently, while");
    println!("  F32 (even with 4-byte optimization) still has overhead from the");
    println!("  remaining byte writes in the medium-fast path.");
}

fn main() {
    analyze_xor_pattern();
    measure_ramp_encoding();
}
